# Let's try adding different patches to find the trigger
# Try all 4 corners, different patch types (white, checkerboard, random), sizes 3-5

def add_patch(images, corner='tl', size=3, patch_type='white'):
    """Add patch to images. corner: tl, tr, bl, br. 1 pixel in from corner."""
    imgs = images.clone().float() / 255.0
    H, W = 32, 32

    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, W - 1 - size
    elif corner == 'bl':
        r_start, c_start = H - 1 - size, 1
    elif corner == 'br':
        r_start, c_start = H - 1 - size, W - 1 - size

    for i in range(len(imgs)):
        if patch_type == 'white':
            patch = torch.ones(3, size, size)
        elif patch_type == 'checkerboard':
            # Create checkerboard
            patch = torch.zeros(3, size, size)
            for c in range(3):
                for r in range(size):
                    for col in range(size):
                        if (r + col) % 2 == 0:
                            patch[c, r, col] = 1.0
        elif patch_type == 'random':
            patch = torch.randint(0, 2, (3, size, size)).float()

        imgs[i, :, r_start:r_start+size, c_start:c_start+size] = patch

    # Denormalize to uint8
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    imgs = (imgs * std + mean) * 255
    return imgs.clamp(0, 255).to(torch.uint8)

